<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · PhotoSphere</h1>
      <p class="demo-page__lead">
        来自 video-code 的「3D 照片球（支持上传版）」：照片按 Fibonacci 球面均匀铺在球壳上，拖动旋转、
        松手带惯性，背面照片压暗，点一张能放大看大图。原 demo 还带「上传图片」（多选 + canvas 压缩后覆盖）、
        「导出 HTML」「自动播放」「全屏展示」；组件里保留了最核心的球体 + 上传，图片改由 <code>images</code>
        传入、上传结果通过 <code>update:images</code> 抛回宿主，导出和全屏这类页面级能力没带进来。
      </p>
    </header>

    <section class="ps-demo">
      <div class="ps-demo__head">
        <h2 class="demo-page__section-title">拖一拖 · 点一点 · 传一传</h2>
        <code class="ps-demo__tag">drag / zoom / upload</code>
      </div>
      <p class="demo-card__text">
        下面这颗球用的是 12 张生成的渐变图（不依赖外网）；按住拖动可以任意角度旋转，松手会顺着惯性再转一会儿。
        点任意一张缩略图能看大图，点空白处或按 Esc 关闭。底部「上传图片」可以多选本地照片，会压缩后替换掉列表。
      </p>

      <div class="ps-demo__stage">
        <PhotoSphere
          :images="images"
          :size="520"
          :thumb-size="76"
          @update:images="onImagesChange"
          @upload="onUpload"
          @pick="onPick"
        />
      </div>

      <p class="ps-demo__hint">
        当前 <code>{{ images.length }}</code> 张 · 最近点开：<code>{{ picked }}</code> ·
        {{ uploadNote }}
      </p>

      <div class="ps-demo__row">
        <PhotoSphere
          :images="images.slice(0, 14)"
          :size="300"
          :thumb-size="46"
          :radius="118"
          :auto-speed="0.12"
          :upload="false"
          class="ps-demo__small"
        />
        <div class="ps-demo__note">
          <p>
            右边这颗是同一份图片的小尺寸版本：<code>size</code> 缩到 300、缩略图 46、
            半径固定 118、自转速度翻倍，并关掉了上传条（<code>:upload="false"</code>）。
          </p>
          <p>
            球面分布用的是黄金角 + <code>(i+0.5)/n</code> 的高度采样，所以图少时也不会挤在两极；
            正 / 背面每帧按旋转矩阵算一次 <code>viewZ</code>，只有状态变化时才写回 DOM。
          </p>
        </div>
      </div>
    </section>

    <DemoPreview class="ps-preview">
      <LevaPlayground
        name="PhotoSphere"
        :component="PhotoSphere"
        :schema="PhotoSphereSchema"
        :presets="{ images }"
        :listeners="{
          'update:images': (next: string[]) => onImagesChange(next),
          pick: (src: string) => onPick(src),
        }"
        stage-class="is-dark"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>size</code> / <code>thumbSize</code> / <code>radius</code>（0 = 按 size 自动）调尺寸，
        <code>maxItems</code> 限制最多展示几张，<code>autoSpeed</code> 是空闲自转速度、
        <code>sensitivity</code> 是拖拽灵敏度、<code>friction</code> 是松手后的惯性衰减，
        <code>maxUploadSize</code> 是上传压缩的最长边。<code>images</code> 是数组（面板不生成控件），
        换图片直接传 <code>:images="[...]"</code>。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import PhotoSphereSchema from '@melt-js/comps-vue3/src/components/PhotoSphere.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const PhotoSphere = remoteComponent('PhotoSphere')

const PALETTE = [
  ['#f97316', '#ec4899'],
  ['#22d3ee', '#3b82f6'],
  ['#a855f7', '#6366f1'],
  ['#34d399', '#14b8a6'],
  ['#fbbf24', '#f97316'],
  ['#f472b6', '#a855f7'],
  ['#38bdf8', '#818cf8'],
  ['#4ade80', '#22d3ee'],
  ['#fb7185', '#fbbf24'],
  ['#c084fc', '#38bdf8'],
  ['#facc15', '#4ade80'],
  ['#fda4af', '#c084fc'],
]

/** 用内联 SVG 生成一批渐变底图，免得 demo 依赖外网图片 */
function makeTile(index: number): string {
  const [from, to] = PALETTE[index % PALETTE.length]
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240">
    <defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/>
    </linearGradient></defs>
    <rect width="240" height="240" fill="url(#g)"/>
    <text x="120" y="136" font-family="sans-serif" font-size="92" font-weight="700"
      fill="rgba(255,255,255,0.88)" text-anchor="middle">${index + 1}</text>
  </svg>`
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`
}

const images = ref<string[]>(Array.from({ length: 12 }, (_, index) => makeTile(index)))
const picked = ref('（还没点过）')
const uploadNote = ref('还没上传过新图')

const stageStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  height: '620px',
  padding: '24px',
  background: 'radial-gradient(circle at 50% 40%, #22304a, #0e1420 60%, #070a10)',
}

function onImagesChange(next: string[]) {
  images.value = next
}

function onUpload(next: string[]) {
  uploadNote.value = `刚上传了 ${next.length} 张（已压到最长边 1200px 的 JPEG）`
}

function onPick(src: string) {
  picked.value = `第 ${images.value.indexOf(src) + 1} 张`
}
</script>

